{
  "headline": "FDA's records trace our supply to a plant classified OAI 202 days before the shortage posting",
  "headline_cites": ["D14"],
  "sentences": [
    {
      "text": "FDA first posted the lidocaine hydrochloride shortage on 2012-02-22 and it remains current as of 2026-10-21.",
      "cites": ["E81", "D26"]
    },
    {
      "text": "Multiple manufacturers are listed on the FDA shortage list including Amphastar, B. Braun, Baxter, Eugia, Fresenius Kabi, Hikma, Hospira, and others.",
      "cites": ["E71", "E73", "E74", "E75", "E76", "E77", "E78"]
    },
    {
      "text": "FDA inspection 740633 at Hospira, Inc. ended 2011-08-04 and was classified OAI with Form 483 observations for scientifically sound laboratory controls and investigation of discrepancies, 202 days before the shortage posting.",
      "cites": ["D14", "E60"]
    },
    {
      "text": "FDA inspection 732886 at Hospira, Inc. ended 2011-06-17 and was classified OAI with 17 observations including control procedures and lack of written stability program, 250 days before the shortage posting.",
      "cites": ["D12", "E58"]
    },
    {
      "text": "FDA inspection 639034 at Hospira, Inc. ended 2010-01-19 and was classified OAI with 6 observations, 764 days before the shortage posting.",
      "cites": ["D10", "E56"]
    },
    {
      "text": "A Warning Letter was issued to Hospira, Inc. on 2010-04-12, 681 days before the shortage posting.",
      "cites": ["D11", "E65"]
    },
    {
      "text": "The recommended action is to transfer 204 units from Corvale East to Corvale Lakeside, which would give Corvale Lakeside 14 days on hand while Corvale East maintains two weeks of supply.",
      "cites": ["D23"]
    }
  ]
}
